temId":"d8d1fbf1-04e6-5030-9613-b5869a47fdef","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"3e218104-62e5-44ce-923d-c1b2b84286bf","sourceKey":"quiz:79","parentItemId":null,"payload":{"prompt":"Models in which at least one parameter or decision variable is a random variable are called:","options":["Standard models","Deterministic models","Static models","Probabilistic models"],"correctOption":3,"section":"Section F — Operational Modelling: Model Theory & Linear Programming"}},{"itemId":"a2c66042-38a0-588b-87fa-62674406b17d","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"3800d6a3-3887-4b53-a1d2-2f1e35b2c964","sourceKey":"quiz:80","parentItemId":null,"payload":{"prompt":"Models that assume all parameters and functional relationships are known with certainty are called:","options":["Deterministic models","Custom-made models","Dynamic models","Probabilistic models"],"correctOption":0,"section":"Section F — Operational Modelling: Model Theory & Linear Programming"}},{"itemId":"49cb35fd-6bf1-50f6-8301-307f4c594d08","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"8b457dec-e46f-42b2-8254-cc27d67655f4","sourceKey":"quiz:81","parentItemId":null,"payload":{"prompt":"Ragsdale's model category with known, precise functional relationships, where independent variables are known or under the decision maker's control, is called:","options":["Predictive models","Prescriptive models","Analogue models","Descriptive models"],"correctOption":1,"section":"Section F — Operational Modelling: Model Theory & Linear Programming"}},{"itemId":"9303aaf7-2a29-52ff-8324-3e659642ca55","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"d841c60c-04c5-448d-ba11-b4bdf304b535","sourceKey":"quiz:82","parentItemId":null,"payload":{"prompt":"Which of these is an example of a Predictive model (Ragsdale)?","options":["Goal programming","CPM","Linear programming","Regression analysis"],"correctOption":3,"section":"Section F — Operational Modelling: Model Theory & Linear Programming"}},{"itemId":"0b128b36-48e1-53bd-bb3c-bc2bcb397c09","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"80c93058-b1a7-484e-9124-1f9f75bca38b","sourceKey":"quiz:83","parentItemId":null,"payload":{"prompt":"Which of the 5 categories of decision-making variables represents factors outside the decision maker's control, such as competitor actions?","options":["Decision Variables","Performance Measures","Exogenous Variables","Intermediate Variables"],"correctOption":2,"section":"Section F — Operational Modelling: Model Theory & Linear Programming"}},{"itemId":"67dd0392-ef7f-5494-8039-ed12df36b645","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"fb8957ee-847d-43f3-ad07-d7df14c8c176","sourceKey":"quiz:84","parentItemId":null,"payload":{"prompt":"In Linear Programming, the objective function:","options":["Cannot include decision variables","Must always equal zero","Represents resource limitations","Is the function to maximise or minimise"],"correctOption":3,"section":"Section F — Operational Modelling: Model Theory & Linear Programming"}},{"itemId":"9a7bffbb-9bf1-5e78-9c26-24bcf72cd5ce","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"ee32367f-5e80-4db4-8ad4-5f7e7f8e3d89","sourceKey":"quiz:85","parentItemId":null,"payload":{"prompt":"In LP, the feasible region is:","options":["The objective function line","The area outside all constraint lines","A single point","The area satisfying all constraints simultaneously"],"correctOption":3,"section":"Section F — Operational Modelling: Model Theory & Linear Programming"}},{"itemId":"306bc50f-1d6f-523d-aa19-be9f978681e9","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"40bfe3d8-bed8-4831-9cb2-553ac61aa914","sourceKey":"quiz:86","parentItemId":null,"payload":{"prompt":"In the graphical LP method, the optimal solution is found at:","options":["The centre of the feasible region","A corner (vertex) of the feasible region","The origin only","Any random point in the feasible region"],"correctOption":1,"section":"Section F — Operational Modelling: Model Theory & Linear Programming"}},{"itemId":"7b4ffafd-de2e-560e-8bde-67d3caee966b","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"881b3123-85c1-4454-be56-c411ebe52cb7","sourceKey":"quiz:87","parentItemId":null,"payload":{"prompt":"In the class worked example (Maximise Z = 5x + 4y, subject to 6x+4y≤24, x+2y≤6), what is the optimal solution?","options":["x = 0, y = 0, Z = 0","x = 3, y = 1.5, Z = 21","x = 4, y = 0, Z = 20","x = 0, y = 3, Z = 12"],"correctOption":1,"section":"Section F — Operational Modelling: Model Theory & Linear Programming"}},{"itemId":"9c8c75e3-405a-5fbc-a593-d5711faa5fee","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"7f8ab39a-1f79-4667-8b18-d9e478e2a788","sourceKey":"quiz:88","parentItemId":null,"payload":{"prompt":"LP applied to minimising the cost of shipping goods from sources to destinations is called:","options":["Production Scheduling","Transportation Planning","Capacity Planning","Inventory Optimisation SECTION G Decision Theory and Managerial Decision-Making Dr. A. G. Adekoya | Session 6 | 36 Questions"],"correctOption":1,"section":"Section F — Operational Modelling: Model Theory & Linear Programming"}},{"itemId":"1224b53e-0523-5d1e-8b5f-55c1d2130494","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"a95937e5-b21d-457f-a1df-493443c8f931","sourceKey":"quiz:89","parentItemId":null,"payload":{"prompt":"Which decision-making environment uses EMV and Decision Trees?","options":["Ambiguity","Uncertainty","Certainty","Risk"],"correctOption":3,"section":"Section G — Decision Theory and Managerial Decision-Making"}},{"itemId":"22a288db-6667-5dba-a05f-9a3c2f1c936a","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"c6852cdd-5ea9-4c3d-a455-7d28cf66fdf7","sourceKey":"quiz:90","parentItemId":null,"payload":{"prompt":"Choosing the alternative with the maximum possible payoff describes:","options":["Maximin (Pessimistic)","Minimax Regret","Maximax (Optimistic)","Equally Likely (Laplace)"],"correctOption":2,"section":"Section G — Decision Theory and Managerial Decision-Making"}},{"itemId":"8533f580-44d2-561e-b175-8eb2d155ab9d","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"37678ace-2685-4ef8-b4ba-9b4950b15542","sourceKey":"quiz:91","parentItemId":null,"payload":{"prompt":"Choosing the alternative that maximises the minimum payoff describes:","options":["Maximax (Optimistic)","Criterion of Realism (Hurwicz)","Equally Likely (Laplace)","Maximin (Pessimistic)"],"correctOption":3,"section":"Section G — Decision Theory and Managerial Decision-Making"}},{"itemId":"662b8a51-8cf0-54fd-992b-0d7b24fa55c2","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"65781e91-7bb2-4ba2-abcf-3873f919b85c","sourceKey":"quiz:92","parentItemId":null,"payload":{"prompt":"Minimising the maximum opportunity loss describes:","options":["Maximax","Equally Likely (Laplace)","Minimax Regret","Maximin"],"correctOption":2,"section":"Section G — Decision Theory and Managerial Decision-Making"}},{"itemId":"a3693e0e-e173-5661-8977-d3f8f0613b1c","courseId":"40000000-0000-4000-8000-000000000012","kind":"cbt_question","questionId":"44626001-6c89-43d0-b969-097f170340d4","sourceKey":"quiz:93","parentItemId":null,"payload":{"prompt":"The Hurwicz (Criterion of Realism) formula is:","options":["α × Max + (1 − α) × Min","Min payoff only","Average of all payoffs","Max payoff only"],"correctOption":0,"section":"Section G — Decision Theory and Managerial Decision-Making"}},{"itemId":"02ab7b2b-a342-5536-a634-c1f69133db8c","courseId":"40000000-0000-4000-8000-000000000012","